@using sv_bd032274e0184148aadd5077899152a1.Services
@inject IJSRuntime JS

<div class="message-area">
    <div class="area-header">
        <h2># @ChannelName</h2>
        <p>@ChannelDescription</p>
    </div>

    <div class="message-list" @ref="_messageListRef">
        @if (_loadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        @if (!HasMore && Messages.Count > 0)
        {
            <div class="beginning-indicator">Beginning of #@ChannelName</div>
        }
        @foreach (var msg in Messages)
        {
            <MessageItem Message="msg"
                         ReplyCount="GetReplyCount(msg.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <div class="message-input-area">
        <textarea @bind="NewMessage" @bind:event="oninput"
                  @onkeydown="OnKeyDown"
                  placeholder="Message #@ChannelName"
                  rows="1"></textarea>
        <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(NewMessage)">
            Send
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private string NewMessage { get; set; } = "";
    private ElementReference _messageListRef;
    private bool _loadingMore;
    private bool _shouldScrollToBottom = true;
    private DotNetObjectReference<MessageArea>? _dotNetRef;
    private IJSObjectReference? _scrollModule;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _scrollModule = await JS.InvokeAsync<IJSObjectReference>("import",
                "./_content/sv-bd032274e0184148aadd5077899152a1/Components/Pages/Chat/MessageArea.razor.js");
            await _scrollModule.InvokeVoidAsync("initScrollListener", _messageListRef, _dotNetRef);
        }

        if (_shouldScrollToBottom)
        {
            _shouldScrollToBottom = false;
            if (_scrollModule is not null)
            {
                await _scrollModule.InvokeVoidAsync("scrollToBottom", _messageListRef);
            }
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (_loadingMore || !HasMore) return;
        _loadingMore = true;
        StateHasChanged();
        await OnLoadMore.InvokeAsync();
        _loadingMore = false;
        StateHasChanged();
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(NewMessage)) return;
        var content = NewMessage;
        NewMessage = "";
        _shouldScrollToBottom = true;
        await OnSendMessage.InvokeAsync(content);
    }

    private async Task OnKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessage();
        }
    }

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.GetValueOrDefault(messageId);

    public async ValueTask DisposeAsync()
    {
        if (_scrollModule is not null)
        {
            try { await _scrollModule.DisposeAsync(); }
            catch (JSDisconnectedException) { }
        }
        _dotNetRef?.Dispose();
    }
}

export function scrollToBottom(element) {
    if (element) {
        element.scrollTop = element.scrollHeight;
    }
}

export function initScrollListener(element, dotNetRef) {
    if (!element) return;
    element.addEventListener('scroll', () => {
        if (element.scrollTop === 0) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    });
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
    overflow: hidden;
}

.area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.area-header h2 {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 700;
    color: #1a1a1a;
}

.area-header p {
    margin: 2px 0 0;
    font-size: 0.82rem;
    color: #777;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.loading-indicator,
.beginning-indicator {
    text-align: center;
    padding: 12px;
    font-size: 0.82rem;
    color: #999;
}

.message-input-area {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.message-input-area textarea {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    line-height: 1.4;
    outline: none;
    transition: border-color 0.15s;
}

.message-input-area textarea:focus {
    border-color: #1264a3;
}

.send-btn {
    padding: 10px 20px;
    background: #1264a3;
    color: #fff;
    border: none;
    border-radius: 8px;
    font-weight: 600;
    font-size: 0.88rem;
    cursor: pointer;
    transition: background 0.15s;
    flex-shrink: 0;
}

.send-btn:hover:not(:disabled) {
    background: #0e4f82;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: default;
}

