        _messages = [];
        _hasMore = true;
        _threadOpen = false;
        _threadMessages = [];
        _threadRootMessage = null;

        var messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = messages;
        _hasMore = messages.Count >= PageSize;

        await ChatService.MarkChannelReadAsync(channelId);
        await RefreshThreadReplyCounts();

        // Refresh channels to update unread counts
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessages()
    {
        if (!_hasMore || _activeChannel is null) return;

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messages.Count, PageSize);
        if (older.Count < PageSize) _hasMore = false;
        _messages.InsertRange(0, older);
        await RefreshThreadReplyCounts();
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootMessageId = rootMessageId;
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
    }

    private async Task SendThreadReply(string content)
    {
        if (_activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessageId);
        _threadMessages.Add(reply);

        // Update reply count
        _threadReplyCounts[_threadRootMessageId] = _threadMessages.Count;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadMessages = [];
        _threadRootMessage = null;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh messages to show updated reactions
        if (_activeChannel is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messages.Count);
            _messages = refreshed;
        }
    }

    private async Task RefreshThreadReplyCounts()
    {
        _threadReplyCounts = [];
        // Only root messages (those not replying to anything) can be thread starters
        var rootIds = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToList();

        foreach (var rootId in rootIds)
        {
            var thread = await ChatService.GetThreadAsync(rootId);
            if (thread.Count > 0)
            {
                _threadReplyCounts[rootId] = thread.Count;
            }
        }
    }

    public ValueTask DisposeAsync()
    {
        _cts.Cancel();
        _cts.Dispose();
        return ValueTask.CompletedTask;
    }
